!function(r){function t(t){for(var e,p,o=t[0],u=t[1],m=t[2],s=0,g=[];s<o.length;s++)p=o[s],Object.prototype.hasOwnProperty.call(i,p)&&i[p]&&g.push(i[p][0]),i[p]=0;for(e in u)Object.prototype.hasOwnProperty.call(u,e)&&(r[e]=u[e]);for(c&&c(t);g.length;)g.shift()();return n.push.apply(n,m||[]),a()}function a(){for(var r,t=0;t<n.length;t++){for(var a,p=n[t],o=!0,u=1;u<p.length;u++)a=p[u],0!==i[a]&&(o=!1);o&&(n.splice(t--,1),r=e(e.s=p[0]))}return r}function e(t){if(p[t])return p[t].exports;var a=p[t]={i:t,l:!1,exports:{}};return r[t].call(a.exports,a,a.exports,e),a.l=!0,a.exports}var p={},i={20:0},n=[];e.m=r,e.c=p,e.d=function(r,t,a){e.o(r,t)||Object.defineProperty(r,t,{enumerable:!0,get:a})},e.r=function(r){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(r,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(r,"__esModule",{value:!0})},e.t=function(r,t){if(1&t&&(r=e(r)),8&t)return r;if(4&t&&"object"==typeof r&&r&&r.__esModule)return r;var a=Object.create(null);if(e.r(a),Object.defineProperty(a,"default",{enumerable:!0,value:r}),2&t&&"string"!=typeof r)for(var p in r)e.d(a,p,function(t){return r[t]}.bind(null,p));return a},e.n=function(r){var t=r&&r.__esModule?function(){return r.default}:function(){return r};return e.d(t,"a",t),t},e.o=function(r,t){return Object.prototype.hasOwnProperty.call(r,t)},e.p="";var o=window.webpackJsonp=window.webpackJsonp||[],u=o.push.bind(o);o.push=t,o=o.slice();for(var m=0;m<o.length;m++)t(o[m]);var c=u;n.push([50,0]),a()}({50:function(r,t,a){"use strict";a.r(t);var e=a(0);Object(e.a)("ru","army",a(51),a(1))},51:function(r){r.exports=JSON.parse('{"category":[{"name":"苏联","link":"ru_shortcut"},{"name":"陆战武器","link":"ru_army"},{"name":"轮式装甲车与半履带军车","link":"ru_army#ru_army_av"}],"model":"苏军轻型（4轮）装甲车","description":"<h6>综述：</h6><p>苏军的轻型（4轮）装甲车大部份都是在二战前研制的，其型号有D系列的D-8、D-12和BA系列的BA-20和BA-64，此外还有FAI型等。D系列的轻型装甲车在二战苏德战争开始时已基本被淘汰，FAI轻型装甲车尽管产量很大，但参加的战斗大多都在二战前，到1943年也基本退出战场，而真正投入二战的轻型装甲车主要是BA-20和BA-64型。这二型轻型装甲车虽然火力与装甲都不强，但其车速高，机动性强，大多配备在苏军的机械化部队中，担任先头侦察任务，也会在必要时候作步兵的火力支援以及布雷工作。</p>","part1title":"系列型号","part1description":"","part1content":[{"image":"imgs/ru/army/ru_army_wav4_20.jpg","description":"<h6>BA-20轻型装甲车</h6><p>BA-20轻型装甲车是在苏联GAZ-M1四轮越野卡车底盘基础上设计制造的，其车上配有烟雾发射器和地雷，是苏军一种具备侦察、布雷等功能的多用途轻型装甲车。战前一共生产了2056辆，二战初、中期仍在苏联战场上坚持作战。</p><p>基本技术数据：</p><p>车长：4.31米，车宽：1.75米，车高：2.13米，车重：2.5吨；乘员：2～3人；</p><p>最高车速：85千米/小时，最大行程：450千米；</p><p>装甲厚度：4～6毫米；</p><p>武器配备：一挺7.62毫米TD TMG型机枪。</p>","caption":""},{"image":"imgs/ru/army/ru_army_wav4_30.jpg","description":"<h6>BA-64轻型装甲车</h6><p>BA-64是苏军第一种采用四轮驱动的装甲车，该车配装了动力较强且整体性能较好的发动机，除了能涉水和爬坡外，还能在恶劣条件下使用低标燃料。BA-64轻型装甲车由于有良好的机动性，因此十分胜任侦察任务，其机枪火力虽不强，但也会担任步兵支援任务，甚至能对空射击造成对低空飞行敌机的干扰。二战期间，苏军共接收了8100多辆BA-64，其中改进型的BA-64B就有5000多辆，并有3000多辆配备了无线电通讯装置，这些装甲车大多投入了东线苏联战场，亦有少数分给了盟军使用，直到战后还有一些在作训练车用。</p><p>基本技术数据：</p><p>车长：3.66米，车宽：1.69米，车高：1.9米，车重：2.36吨；</p><p>最高车速：80千米/小时，最大行程：600千米；</p><p>武器配备：一挺7.62毫米机枪。</p>","caption":""},{"image":"imgs/ru/army/ru_army_wav4_40.jpg","description":"<h6>FAI轻型装甲车</h6><p>FAI轻型装甲车是在1932年研发，1933年开始量产，是苏联产量最大的一种装甲车；其炮塔可以手动旋转，机动性也不错，在苏军中主要担负侦察任务，从1929年至1943年，FAI轻型装甲车跟随苏军部队参加了多场战斗，也有不少战车一直使用到二战结束。</p><p>基本技术数据：</p><p>车长：3.75米，车宽：1.68米，车高：2.24米，车重：2.0吨；</p><p>最高车速：80千米/小时，最大行程：200千米；</p><p>武器配备：一挺7.62毫米DA型机枪。</p>","caption":""}],"part2title":"战场上的苏军轻型（4轮）装甲车","part2description":"","part2content":[{"image":"imgs/ru/army/ru_army_wav4_27.jpg","description":"1940年2月，芬兰战场，苏军一辆不明单位的BA-20轻型装甲车。","caption":""},{"image":"imgs/ru/army/ru_army_wav4_20.jpg","description":"1942年11月在东线苏联战场作战，隶属苏联西方面军第20装甲旅的一辆BA-20轻型装甲车。","caption":""},{"image":"imgs/ru/army/ru_army_wav4_21.jpg","description":"1942年9月，东线苏联战场，在坚守斯大林格勒防御作战中的苏军不明单位（编号为1502）的一辆BA-20轻型装甲车。","caption":""},{"image":"imgs/ru/army/ru_army_wav4_22.jpg","description":"1942年6月，波兰战场上隶属苏联第8机械化军第12装甲师第24坦克团的一辆BA-20轻型装甲车。","caption":""},{"image":"imgs/ru/army/ru_army_wav4_23.jpg","description":"1939年10月，苏军一指挥官向装甲车部队下命令：前进越过爱沙尼亚边境。军官后面是一队BA-20轻型装甲车。","caption":""},{"image":"imgs/ru/army/ru_army_wav4_24.jpg","description":"1941年7月，东线苏联战场，苏军一队BA-20轻型装甲车正向前线开进。","caption":""},{"image":"imgs/ru/army/ru_army_wav4_25.jpg","description":"1942年7月，东线苏联战场，隶属苏联西方方面军的装甲车部队正待命出发，图中的装甲车分别是BA-20M型、BA-10型和BA-6型。","caption":""},{"image":"imgs/ru/army/ru_army_wav4_26.jpg","description":"1943年，东线苏联战场，苏联加里宁方面军的一辆沿铁轨行进的BA-20M轻型装甲车由于铁轨问题而停止前进，车组乘员正在进行维修。","caption":""},{"image":"imgs/ru/army/ru_army_wav4_31.jpg","description":"1945年1月，东线苏联战场，隶属苏联乌克兰方面军一辆不明单位（编号为091）的BA-64轻型装甲车。","caption":""},{"image":"imgs/ru/army/ru_army_wav4_32.jpg","description":"1944年8月，东线战场罗马尼亚布加勒斯特，隶属苏联第2乌克兰方面军第6坦克军第6独立摩托化团的一辆BA-64轻型装甲车。","caption":""},{"image":"imgs/ru/army/ru_army_wav4_41.jpg","description":"1939年7月，苏军第9装甲车旅的一辆FAI轻型装甲车。","caption":""},{"image":"imgs/ru/army/ru_army_wav4_42.jpg","description":"1944年8月，波兰首都华沙起义中的一辆FAI轻型装甲车。 ","caption":""}]}')}});